.fold-btns{display:flex;gap:8px;margin:0 14px 8px;flex-wrap:wrap}
.fold-btns button{font-family:'Noto Sans KR',sans-serif;font-weight:700;font-size:15px;border:1.5px solid var(--ink);background:var(--paper);padding:9px 12px;cursor:pointer;color:var(--ink)}
.fold-btns button.main{background:var(--ink);color:var(--paper)}
.fold-btns button:disabled{opacity:.35;cursor:default}
.fold-stat{font-family:'Noto Sans KR',sans-serif;font-weight:900;font-size:18px;margin:4px 14px 0}
.fold-eq{font-family:'Noto Sans KR',sans-serif;font-size:14.5px;color:var(--red);font-weight:700;margin:2px 14px 8px;min-height:20px}
.fold-views{display:flex;gap:10px;justify-content:center;flex-wrap:wrap;margin:0 14px}
.fold-view{display:flex;flex-direction:column;align-items:center}
.fold-view .lab{font-family:'Noto Sans KR',sans-serif;font-size:12.5px;font-weight:700;color:var(--gray);margin-bottom:4px}
.fold-view canvas{display:block;border:1px solid var(--line);background:#fff;max-width:100%}
#foldPaper{width:360px;aspect-ratio:1/1}
#foldThick{width:200px;aspect-ratio:200/360}
.fold-size{font-family:'Noto Sans KR',sans-serif;font-size:13px;color:var(--gray);margin-top:4px}
.fold-msg{font-family:'Noto Sans KR',sans-serif;font-size:14.5px;line-height:1.6;margin:10px 14px 0;background:#FFF3D6;border-left:4px solid var(--red);padding:8px 10px;min-height:24px}
.fold-imag{margin:12px 14px 0;border:1.5px solid var(--ink);background:var(--paper);padding:8px 10px}
.fold-imag .t{font-family:'Noto Sans KR',sans-serif;font-weight:900;font-size:14px}
.fold-imag .row{display:flex;align-items:center;gap:8px;margin-top:6px}
.fold-imag input[type=range]{flex:1;accent-color:var(--red)}
.fold-imag #foldImN{font-family:'Noto Sans KR',sans-serif;font-weight:900;min-width:44px;text-align:right}
.fold-imag .out{font-family:'Noto Sans KR',sans-serif;font-size:14.5px;line-height:1.65;margin-top:6px}
.fold-imag .out b{color:var(--red)}
.fold-tw{overflow-x:auto;margin:12px 14px 0}
.fold-tbl{width:100%;border-collapse:collapse;font-family:'Noto Sans KR',sans-serif;font-size:13.5px}
.fold-tbl th{background:var(--ink);color:var(--paper);font-weight:700;padding:5px 6px;text-align:right;white-space:nowrap}
.fold-tbl td{border-bottom:1px solid var(--line);padding:4px 6px;text-align:right;white-space:nowrap}
.fold-tbl tr.new td{background:#FFF3D6}
.fold-tbl tr.imag td{color:var(--navy);font-style:italic}
.fold-note{font-family:'Noto Sans KR',sans-serif;font-size:13px;color:var(--gray);line-height:1.6;margin:10px 14px 0}
@media (max-width:520px){ #foldPaper{width:100%} #foldThick{width:60%} }

