/* ---------- 뒤집고 돌려서 눈송이 만들기 (template_v3.html simHtml/bindSim 방식) ---------- */
function snowSimHtml(){
  return `<div class="sim snow-sim" id="snowSim">
    <div class="sim-head">직접 해 보기 · 뒤집고 돌려서 눈송이 만들기</div>
    <p class="sim-goal">깃발을 밀고, 뒤집고, 돌려 봐요. <b>오른쪽으로 뒤집고 이어서 아래쪽으로 뒤집으면</b> 어떤 돌리기와 같아질까요? 그다음 아래 판에서 눈송이도 그려 보세요.</p>
    <div class="snow-part">① 도형 움직이기</div>
    <div class="snow-btns">
      <button class="main" data-a="slide">밀기 →</button>
      <button class="main" data-a="flipR">오른쪽으로 뒤집기</button>
      <button class="main" data-a="flipD">아래쪽으로 뒤집기</button>
      <button class="main" data-a="rot">시계 방향 90° 돌리기</button>
      <button id="snowReset">처음으로</button>
    </div>
    <canvas id="snowFlag" width="520" height="220" aria-label="깃발 모양 움직이기"></canvas>
    <div class="snow-judge" id="snowJudge"></div>
    <div class="snow-log" id="snowLog"></div>
    <div class="snow-msg" id="snowMsg"></div>
    <div class="snow-part">② 눈송이 그리기판</div>
    <div class="snow-btns">
      <button id="snowMir" class="on">뒤집기 켜짐</button>
      <button data-n="6" class="on">6갈래</button><button data-n="4">4갈래</button><button data-n="8">8갈래</button>
      <button id="snowEx">보기 예시</button>
      <button id="snowClear">지우기</button>
    </div>
    <canvas id="snowPad" width="360" height="360" aria-label="눈송이 그리기판"></canvas>
    <div class="snow-count" id="snowCount"></div>
    <div class="snow-msg" id="snowMsg2"></div>
  </div>`;
}
function bindSnowSim(){
  const root = document.getElementById("snowSim"); if (!root) return;
  const $s = id => document.getElementById(id);
  /* ----- ① 깃발: 상태는 2×2 정수 행렬 [a,b,c,d] (화면 좌표, y는 아래로) ----- */
  const cv = $s("snowFlag"), fx = cv.getContext("2d"), CELL = 20, W = 520, HH = 220;
  const mul = (A, B) => [A[0]*B[0]+A[1]*B[2], A[0]*B[1]+A[1]*B[3], A[2]*B[0]+A[3]*B[2], A[2]*B[1]+A[3]*B[3]];
  const I = [1,0,0,1], R = [0,-1,1,0], FLR = [-1,0,0,1], FUD = [1,0,0,-1];
  const R2 = mul(R, R), R3 = mul(R, R2);
  const same = (A, B) => A.every((v, i) => v === B[i]);
  const NAMES = [[I, "처음 모양 그대로"], [R, "시계 방향으로 90° 돌린 것"], [R2, "180° 돌린 것"], [R3, "시계 방향으로 270° 돌린 것"], [FLR, "오른쪽으로 뒤집은 것"], [FUD, "아래쪽으로 뒤집은 것"]];
  const judge = M => { for (const [A, nm] of NAMES) if (same(M, A)) return nm; return "뒤집기와 돌리기를 섞어야 나오는 모양"; };
  // 깃발 모양(가운데 기준, 칸 단위): 깃대 세로 3칸, 깃발은 위쪽 오른편 세모
  const POLE = [[0, -1.5], [0, 1.5]], FLAG = [[0, -1.5], [1.3, -1], [0, -0.5]];
  let M = I, x0 = 7, x = x0, anim = null, hist = [], rots = 0, flips = 0;
  const Y = 5.5;
  function drawFlag(Mat, cx, ghost){
    const K = 1.6, P = ([u, v]) => [ (cx + K*(Mat[0]*u + Mat[1]*v)) * CELL, (Y + K*(Mat[2]*u + Mat[3]*v)) * CELL ];
    fx.save();
    if (ghost){ fx.setLineDash([5, 4]); fx.strokeStyle = "#A8A091"; fx.lineWidth = 2; }
    // 깃발
    fx.beginPath(); FLAG.forEach((p, i) => { const q = P(p); i ? fx.lineTo(...q) : fx.moveTo(...q); }); fx.closePath();
    if (!ghost){ fx.fillStyle = "#C8372D"; fx.fill(); fx.strokeStyle = "#1C1A17"; fx.lineWidth = 1.6; }
    fx.stroke();
    // 깃대
    fx.beginPath(); fx.moveTo(...P(POLE[0])); fx.lineTo(...P(POLE[1]));
    if (!ghost){ fx.lineWidth = 4; fx.strokeStyle = "#1C1A17"; fx.lineCap = "round"; }
    fx.stroke();
    if (!ghost){ const c = P([0, 0]); fx.beginPath(); fx.arc(c[0], c[1], 3.5, 0, 2*Math.PI); fx.fillStyle = "#1F3A5F"; fx.fill(); }
    fx.restore();
  }
  function grid(){
    fx.clearRect(0, 0, W, HH); fx.fillStyle = "#fff"; fx.fillRect(0, 0, W, HH);
    fx.strokeStyle = "#E6E0D2"; fx.lineWidth = 1;
    for (let i = 0; i <= W; i += CELL){ fx.beginPath(); fx.moveTo(i + .5, 0); fx.lineTo(i + .5, HH); fx.stroke(); }
    for (let j = 0; j <= HH; j += CELL){ fx.beginPath(); fx.moveTo(0, j + .5); fx.lineTo(W, j + .5); fx.stroke(); }
  }
  function render(){
    grid(); drawFlag(I, x0, true);
    if (anim){
      const t = anim.t; let A = I, cx = x;
      if (anim.a === "flipR") A = [1 - 2*t, 0, 0, 1];
      if (anim.a === "flipD") A = [1, 0, 0, 1 - 2*t];
      if (anim.a === "rot"){ const th = t*Math.PI/2; A = [Math.cos(th), -Math.sin(th), Math.sin(th), Math.cos(th)]; }
      if (anim.a === "slide") cx = anim.from + (anim.to - anim.from)*t;
      drawFlag(mul(A, M), cx, false);
    } else drawFlag(M, x, false);
    // 돌리기 가운데 점과 뒤집는 선 안내
    fx.save(); fx.setLineDash([4, 3]); fx.strokeStyle = "rgba(31,58,95,.45)"; fx.lineWidth = 1.2;
    fx.beginPath(); fx.moveTo(x*CELL, (Y - 3.4)*CELL); fx.lineTo(x*CELL, (Y + 3.4)*CELL); fx.moveTo((x - 3.4)*CELL, Y*CELL); fx.lineTo((x + 3.4)*CELL, Y*CELL); fx.stroke(); fx.restore();
  }
  const LABEL = {slide: "밀기", flipR: "오른쪽으로 뒤집기", flipD: "아래쪽으로 뒤집기", rot: "시계 방향 90° 돌리기"};
  function after(a){
    hist.push(a); if (hist.length > 8) hist.shift();
    $s("snowLog").textContent = "한 일: " + hist.map(h => LABEL[h]).join(" → ");
    { const j = judge(M); $s("snowJudge").textContent = same(M, I) ? "지금 모양은 처음 모양과 똑같아요." : (NAMES.some(([A]) => same(M, A)) ? "지금 모양은 처음 모양을 " + j + "과 같아요." : "지금 모양은 " + j + "이에요."); }
    const p = hist[hist.length - 2];
    let m;
    if (a === "slide") m = "밀기는 자리만 바뀌어요. 모양도 방향도 그대로예요.";
    else if ((a === "flipR" && p === "flipD") || (a === "flipD" && p === "flipR")) m = "뒤집기 둘이 만나 180° 돌리기와 같아졌어요. '처음으로'를 누르고 시계 방향 90° 돌리기를 두 번 눌러 확인해 보세요.";
    else if ((a === "flipR" || a === "flipD") && p === a) m = "같은 쪽으로 두 번 뒤집으면 처음 모양으로 돌아와요.";
    else if (a === "rot" && !flips && rots % 4 === 0) m = "90°씩 네 번, 360°를 돌아 한 바퀴. 처음 모양으로 돌아왔어요.";
    else if (a === "rot" && !flips) m = `처음부터 시계 방향으로 모두 ${90*(rots % 4)}° 돌렸어요.`;
    else if (a === "rot") m = "뒤집은 다음 돌리면, 돌리기만으로는 만들 수 없는 모양이 나오기도 해요. 위의 판정 글을 보세요.";
    else m = "뒤집으면 거울에 비춘 것처럼 바뀌어요. 다른 쪽으로도 뒤집어 보세요.";
    $s("snowMsg").textContent = m;
  }
  function act(a){
    if (anim) return;
    const start = performance.now();
    if (a === "slide"){ const to = x + 3 > 23 ? x0 : x + 3; anim = {a, t: 0, from: x, to}; }
    else anim = {a, t: 0};
    const tick = now => {
      anim.t = Math.min(1, (now - start)/400); render();
      if (anim.t < 1) return requestAnimationFrame(tick);
      if (a === "slide") x = anim.to;
      if (a === "flipR"){ M = mul(FLR, M); flips++; }
      if (a === "flipD"){ M = mul(FUD, M); flips++; }
      if (a === "rot"){ M = mul(R, M); rots++; }
      anim = null; render(); after(a);
    };
    requestAnimationFrame(tick);
  }
  function resetFlag(){
    M = I; x = x0; anim = null; hist = []; rots = 0; flips = 0; render();
    $s("snowLog").textContent = ""; $s("snowJudge").textContent = "지금 모양은 처음 모양과 똑같아요.";
    $s("snowMsg").textContent = "깃발을 움직여 봐요. 오른쪽으로 뒤집고 이어서 아래쪽으로 뒤집으면 어떤 돌리기와 같아질까요?";
  }
  root.querySelectorAll("[data-a]").forEach(b => b.onclick = () => act(b.dataset.a));
  $s("snowReset").onclick = resetFlag;
  resetFlag();

  /* ----- ② 눈송이 그리기판 ----- */
  const pv = $s("snowPad"), px = pv.getContext("2d"), S = 360, C = S/2, RAD = 165;
  let n = 6, mir = true, strokes = [], cur = null;
  const wedge = () => 360/(2*n);                       // 그리는 칸의 각도
  const AX = -90;                                       // 가지 한가운데 선(위쪽)
  function inWedge(dx, dy){
    const r = Math.hypot(dx, dy); if (r > RAD) return false;
    let a = Math.atan2(dy, dx)*180/Math.PI;             // 화면 각도(시계 방향이 +)
    return a >= AX - 0.5 && a <= AX + wedge() + 0.5;
  }
  function copies(pt){                                  // 반쪽 1점 → 뒤집기·돌리기로 모든 점
    const out = [], [dx, dy] = pt;
    const base = mir ? [[dx, dy, true], [-dx, dy, false]] : [[dx, dy, true]];
    for (let k = 0; k < n; k++){
      const th = k*2*Math.PI/n, c = Math.cos(th), s = Math.sin(th);
      base.forEach(([u, v, own]) => out.push([c*u - s*v, s*u + c*v, own && k === 0]));
    }
    return out;
  }
  function drawPad(){
    px.clearRect(0, 0, S, S); px.fillStyle = "#fff"; px.fillRect(0, 0, S, S);
    // 칸 경계(옅은 점선)와 그리는 칸(밝게)
    const total = mir ? 2*n : n, step = 360/total;
    px.save(); px.translate(C, C);
    px.fillStyle = "#FFF3D6"; px.beginPath(); px.moveTo(0, 0); px.arc(0, 0, RAD, AX*Math.PI/180, (AX + wedge())*Math.PI/180); px.closePath(); px.fill();
    px.strokeStyle = "rgba(31,58,95,.22)"; px.setLineDash([3, 4]); px.lineWidth = 1;
    for (let i = 0; i < total; i++){ const a = (AX + i*step)*Math.PI/180; px.beginPath(); px.moveTo(0, 0); px.lineTo(RAD*Math.cos(a), RAD*Math.sin(a)); px.stroke(); }
    px.beginPath(); px.arc(0, 0, RAD, 0, 2*Math.PI); px.stroke(); px.setLineDash([]);
    // 선 그리기
    px.lineCap = "round"; px.lineJoin = "round";
    strokes.concat(cur ? [cur] : []).forEach(st => {
      if (st.length < 2) return;
      const cs = st.map(copies);
      for (let j = 0; j < cs[0].length; j++){
        px.beginPath(); px.strokeStyle = cs[0][j][2] ? "#C8372D" : "#1F3A5F"; px.lineWidth = cs[0][j][2] ? 4 : 3;
        cs.forEach((p, i) => i ? px.lineTo(p[j][0], p[j][1]) : px.moveTo(p[j][0], p[j][1])); px.stroke();
      }
    });
    px.beginPath(); px.arc(0, 0, 3, 0, 2*Math.PI); px.fillStyle = "#1C1A17"; px.fill();
    px.restore();
    const pieces = (mir ? 2 : 1)*n;
    $s("snowCount").textContent = `반쪽 1개 × ${mir ? 2 : 1}(뒤집기) × ${n}(돌리기) = ${pieces}개 · 한 칸 ${Math.round(360/pieces*10)/10}°`;
  }
  function msg2(){
    let m;
    if (n !== 6) m = "종이 눈송이는 이렇게 " + n + "갈래로도 만들 수 있지만, 진짜 눈 결정에는 8갈래가 없어요. 진짜는 늘 6갈래예요.";
    else if (!mir) m = "뒤집기를 끄면 가지 양쪽이 닮지 않아 바람개비처럼 보여요. 고른 눈송이는 돌려도, 뒤집어도 같아요.";
    else if (strokes.length) m = "반쪽 1개가 뒤집기로 2개, 60°씩 돌리기로 모두 12개가 됐어요.";
    else m = "노랗게 밝은 칸 안에 가지의 반쪽을 그려 보세요. 나머지는 뒤집기와 돌리기가 만들어 줘요.";
    $s("snowMsg2").textContent = m;
  }
  const pos = e => { const r = pv.getBoundingClientRect(); return [(e.clientX - r.left)*S/r.width - C, (e.clientY - r.top)*S/r.height - C]; };
  pv.addEventListener("pointerdown", e => { const p = pos(e); if (!inWedge(...p)) return; cur = [p]; pv.setPointerCapture(e.pointerId); });
  pv.addEventListener("pointermove", e => { if (!cur) return; const p = pos(e); if (inWedge(...p)) { cur.push(p); drawPad(); } });
  const end = () => { if (cur && cur.length > 1) strokes.push(cur); cur = null; drawPad(); msg2(); };
  pv.addEventListener("pointerup", end); pv.addEventListener("pointercancel", end);
  $s("snowMir").onclick = () => { mir = !mir; $s("snowMir").classList.toggle("on", mir); $s("snowMir").textContent = mir ? "뒤집기 켜짐" : "뒤집기 꺼짐"; drawPad(); msg2(); };
  root.querySelectorAll("[data-n]").forEach(b => b.onclick = () => { n = +b.dataset.n; root.querySelectorAll("[data-n]").forEach(o => o.classList.toggle("on", o === b)); strokes = []; drawPad(); msg2(); });
  $s("snowClear").onclick = () => { strokes = []; drawPad(); msg2(); };
  $s("snowEx").onclick = () => {                        // 줄기 + 60°로 뻗은 곁가지 2개(칸 안에 들어가게 길이 ≤ 뿌리까지 거리)
    const up = [0, -1], br = [Math.sin(Math.PI/3), -Math.cos(Math.PI/3)];
    const P = (d, L) => [[up[0]*d, up[1]*d], [up[0]*d + br[0]*L, up[1]*d + br[1]*L]];
    strokes = [[[0, -8], [0, -RAD + 6]], P(RAD*.42, RAD*.3), P(RAD*.68, RAD*.2), P(RAD*.22, RAD*.14)];
    drawPad(); msg2();
  };
  drawPad(); msg2();
}
